// Generated by tools/build_day.py from source/Day13_NEETSS_ICP_Comparative_Enhanced_Final.docx — do not edit by hand.
window.PORTAL={"day": 13, "title": "Growth & Development", "docTitle": "DAY 13 | GROWTH & DEVELOPMENT", "subtitle": ["NEET-SS + ICP Paediatrics  •  11 October 2026  •  Self-contained learner edition", "Indian clinical framework: IAP Practice Guidelines 2026 + WHO under-5 standards + IAP 2015 charts for 5–18 years. Nelson Pediatrics 22e provides the conceptual foundation; neonatal follow-up cross-links to Cloherty & Stark, IAP-NNF and AIIMS. International recommendations are labelled when used."], "source": "source/Day13_NEETSS_ICP_Comparative_Enhanced_Final.docx", "pages": [{"id": "overview", "title": "Overview", "group": "Start", "kind": "overview", "sections": [{"title": "", "blocks": [{"t": "p", "html": "NEET-SS + ICP Paediatrics  •  11 October 2026  •  Self-contained learner edition"}, {"t": "p", "html": "Indian clinical framework: IAP Practice Guidelines 2026 + WHO under-5 standards + IAP 2015 charts for 5–18 years. Nelson Pediatrics 22e provides the conceptual foundation; neonatal follow-up cross-links to Cloherty &amp; Stark, IAP-NNF and AIIMS. International recommendations are labelled when used."}, {"t": "p", "html": "<strong>TODAY’S COVERAGE  </strong>Growth charts and growth velocity; short stature; growth faltering; developmental milestones and regression; ASD; ADHD; specific learning disorder; sleep disorders/OSA; high-risk neonatal developmental follow-up."}, {"t": "p", "html": "<strong>ASSESSMENT  </strong>75 base MCQs (7 Basic + 13 Conceptual + 27 Clinical + 20 High-Difficulty + 8 Integrated) and 4 EXTRA notebook retests, interleaved. No Calculation Drill on odd-numbered Day 13."}]}, {"title": "Learning Objectives", "h1": "Learning Objectives", "blocks": [{"t": "list", "ordered": false, "items": ["Choose the correct Indian growth reference, calculate velocity and target height, and interpret a longitudinal chart.", "Separate nutritional, endocrine, genetic and systemic growth-failure patterns; identify red flags and test sequencing.", "Recall age-appropriate gross motor, fine motor, social and language milestones; distinguish delay, plateau and regression.", "Apply an Indian-led developmental pathway for ASD, ADHD, SLD and sleep-disordered breathing.", "Interpret simulated growth, developmental-domain and sleep traces; connect neonatal injury with later function.", "Resolve common close distractors and manage risk without treating screening scores as diagnoses."]}]}, {"title": "Objective → case → MCQ map", "h1": "", "blocks": [{"t": "table", "head": ["<strong>Objective</strong>", "<strong>Teaching cases</strong>", "<strong>Question focus</strong>"], "rows": [["Growth trajectory and velocity", "Cases 1–3", "Q1–Q27 and later integrated growth cases"], ["Milestones / corrected age / regression", "Cases 4–5", "Developmental cases throughout Q28–Q79"], ["ASD vs language delay", "Case 6", "Screening versus diagnostic evaluation"], ["ADHD, learning, sleep mimics", "Cases 7–8", "High-difficulty multimorbidity questions"], ["Prior neonatal error repair", "Notebook retests", "Four interleaved extra questions"]]}]}]}, {"id": "part-1", "title": "Standalone Master Notes", "eyebrow": "Part A", "group": "Study Notes", "kind": "notes", "sections": [{"title": "A1. Growth: measurements, references and interpretation", "blocks": [{"t": "p", "html": "Growth is a longitudinal biological process. Height/length reflects linear growth; weight is sensitive to acute intake and illness; head circumference reflects brain/skull growth in infancy; BMI is weight(kg)/height(m)². Plot accurate serial measurements on the correct age- and sex-specific chart. Recumbent length is used below 2 years and standing height thereafter; the two methods are not interchangeable without adjustment. Verify equipment, posture, exact age and prior values before diagnosing a centile shift."}, {"t": "p", "html": "<strong>INDIA — CHART CHOICE (IAP 2026)  </strong>WHO 2006 child growth standards from birth to 5 years; revised IAP 2015 references for 5–18 years. IAP BMI curves use age-specific lines equivalent to adult BMI 23 for overweight and 27 for obesity; do NOT apply BMI 23 or 27 directly to a child’s measured BMI. Preterm growth uses corrected age and appropriate preterm standards (IAP 2026 discusses INTERGROWTH-21st through 2 years corrected age); follow local neonatal follow-up chart conventions consistently."}, {"t": "table", "head": ["<strong>Index</strong>", "<strong>What it measures</strong>", "<strong>Exam interpretation</strong>"], "rows": [["Height/length-for-age", "Linear growth", "&lt;−2 SDS: short stature/stunting; velocity matters"], ["Weight-for-age", "Underweight (mixed acute/chronic)", "&lt;−2 SDS: underweight; cannot distinguish wasting from stunting"], ["Weight-for-length/height", "Relative thinness / wasting", "&lt;−2 SDS wasting; &lt;−3 severe wasting (WHO)"], ["BMI-for-age", "Adiposity relative to height", "For school-age India use IAP age-specific adult-equivalent 23/27 curves"], ["Head circumference-for-age", "Cranial growth", "Serial trend, family head size, prematurity and neuro signs"]]}, {"t": "p", "html": "Z-score = (observed measurement − age/sex reference median) / reference SD (a conceptual simplification; published growth charts use distribution-specific LMS methods). A child can be at the 4th centile but be pathologically falling from the 50th; conversely a stable 2nd-centile child may have a normal familial variant. Centile crossing, growth velocity and deviation from target height often precede overt short stature."}]}, {"title": "A2. Growth velocity and genetic target", "blocks": [{"t": "table", "head": ["<strong>Age</strong>", "<strong>Approximate length/height gain</strong>"], "rows": [["Birth to 1 year", "~25 cm/year"], ["1 to 2 years", "~12 cm/year"], ["2 to 4 years", "~7–8 cm/year"], ["4 years to puberty", "~5–6 cm/year"], ["Pubertal spurt", "~8–12 cm/year (variable by sex/stage)"]]}, {"t": "p", "html": "<strong>FORMULAS  </strong>Annualized height velocity (cm/year) = (height₂ − height₁ in cm) × 12 / months between measurements. Boys MPH = (father + mother + 13 cm)/2; girls MPH = (father + mother − 13 cm)/2. IAP 2026 provides an approximate target interval MPH ±6 cm (clinical estimates vary by reference)."}, {"t": "p", "html": "Height velocity should ideally be assessed from standardized measures separated by at least 6 months, preferably 6–12 months for a prepubertal child. Very short intervals amplify measurement error. Height &lt;−2 SDS, crossing ≥2 major centile lines, disproportion, velocity falling below expected, abnormal puberty, or height discordant with family target warrants evaluation in context. Never diagnose growth hormone deficiency from a single random GH or IGF-1 measurement."}]}, {"title": "A3. Short stature — discriminate patterns before ordering tests", "blocks": [{"t": "table", "head": ["<strong>Pattern</strong>", "<strong>Velocity / bone age / weight</strong>", "<strong>Best inference</strong>"], "rows": [["Familial short stature", "Normal velocity; bone age ~chronological; short genetic target", "Normal variant after red-flag exclusion"], ["Constitutional delay", "Usually preserved prepubertal velocity; bone age delayed; late puberty family history", "Maturational delay; follow puberty and trajectory"], ["Hypothyroidism / GH deficiency", "Falling height velocity; weight relatively preserved/increased; bone age often delayed", "Endocrine investigation indicated"], ["Chronic systemic disease / malabsorption", "Weight often falls before height; GI, renal, cardiac or inflammatory clues", "Targeted systemic workup"], ["Skeletal dysplasia", "Disproportion, limb/trunk ratio abnormalities", "Skeletal/genetic assessment"], ["Syndromic / SGA no catch-up", "Dysmorphism, developmental issues or persistent SGA shortness", "Genetics/endocrine specialist evaluation"]]}, {"t": "p", "html": "First-line assessment: serial measurements; nutrition, medications including glucocorticoids, chronic illness, bowel symptoms, sleep, family heights, puberty, dysmorphism, body proportions and systemic exam. Tests guided by phenotype commonly include CBC, ESR/CRP, renal/liver profile, TSH/free T4, celiac serology (tTG-IgA with total IgA), and left-hand bone age; IGF-1/IGFBP-3 and GH stimulation testing are specialist-context tests. In IgA deficiency, negative tTG-IgA does not exclude celiac disease—use IgG-based testing as indicated."}, {"t": "p", "html": "<strong>SGA FOLLOW-UP  </strong>Approximately 85–90% of SGA children show catch-up by age 2 years. Persistent height SDS below about −2 to −2.5 beyond age 3–4 years warrants endocrine referral after excluding systemic causes; GH eligibility depends on local indication and assessment. Avoid excessive weight catch-up because of later metabolic risk."}]}, {"title": "A4. Growth faltering / failure to thrive", "blocks": [{"t": "p", "html": "IAP 2026 uses growth faltering for downward deviation from expected trajectory, without presuming aetiology. Indicators include repeated weight-for-age below 3rd centile, weight SDS below −2, downward crossing of ≥2 centile lines, or weight–height disproportion. Intake inadequacy is common; also assess malabsorption, increased metabolic demand, psychosocial adversity, endocrine and genetic causes. A normal or rising BMI alongside falling height velocity points away from isolated caloric insufficiency."}, {"t": "p", "html": "Sequence: (1) verify anthropometry and feeding history; (2) separate weight-first, combined weight-and-height, and height-first patterns; (3) look for red flags such as oedema, aspiration, chronic diarrhoea, recurrent severe infection, disproportion and regression; (4) order targeted rather than indiscriminate tests; (5) implement cause-directed feeding support and review weight trajectory, often within 4–8 weeks. Failure to improve triggers broader evaluation. For severe wasting or oedema, use a dedicated malnutrition protocol; management is covered on Day 14."}]}, {"title": "A5. Developmental milestones — IAP 2026 anchors", "blocks": [{"t": "table", "head": ["<strong>Age</strong>", "<strong>Gross motor</strong>", "<strong>Fine motor</strong>", "<strong>Language/social</strong>"], "rows": [["~6 weeks", "Brief chin lift", "Hands often closed", "Social smile, face regard"], ["~3–4 months", "Good head control", "Reaching/hand regard", "Cooing, laughter"], ["~6 months", "Rolls, sits with support", "Transfers hand to hand", "Monosyllables, interactive play"], ["~9 months", "Sits independently, pulls to stand", "Immature pincer", "Bisyllables, waves, stranger anxiety"], ["~12–15 months", "Cruises; walks alone by 12–15 mo", "Mature pincer, 2-block tower", "First true words, gestures, joint attention"], ["~18 months", "Walks/runs with wide base", "3-block tower; spoon", "~8–10 words in IAP table; simple commands"], ["~2 years", "Runs; stairs two feet/step", "6-block tower; horizontal line", "2–3 word phrases, body parts"], ["~3 years", "Tricycle, jumps, one-foot stand", "Copies circle", "Conversation, pretend play"], ["~4 years", "Hops; alternating stair descent", "Copies cross", "Storytelling, cooperative play"], ["~5 years", "Skips", "Copies triangle", "Clear speech and multistep commands"]]}, {"t": "p", "html": "Milestone tables are approximate teaching anchors and vary by reference: IAP 2026 tables are used here. CDC checklists use an approximately 75%-attainment convention, so their ages should not be silently mixed with older median milestone tables. Red flags: loss of any acquired skill; persistent abnormal tone/asymmetry; no babbling/gestures in late infancy; no meaningful words by 16–18 months; absent joint attention or no two-word spontaneous phrases around age 2; poor response to name; progressive neurologic deficits. Assess hearing and vision as appropriate."}, {"t": "p", "html": "<strong>PREMATURITY  </strong>Corrected age = chronological age − (40 − gestational age at birth in weeks). Use for early developmental assessment generally through about 2 years; some follow-up pathways extend correction for very preterm children. Corrected age does not excuse true regression, abnormal tone, persistent asymmetry or social-communication red flags."}]}, {"title": "A6. Developmental delay, GDD, regression and high-risk follow-up", "blocks": [{"t": "p", "html": "Isolated delay involves one domain; global developmental delay means significant impairment in at least two developmental domains in a child generally under 5 years. Intellectual disability requires deficits in intellectual and adaptive functioning with developmental onset, not simply poor grades or IQ alone. Regression is loss of previously acquired abilities and is urgent: consider ASD-related regression, epileptic aphasia/encephalopathy, hearing loss, neurodegeneration, metabolic disease and psychosocial trauma depending on phenotype. Document precise onset, skills lost, associated seizures and examination."}, {"t": "p", "html": "Early CP prediction integrates general movements (absent fidgety at corrected 3–5 months), HINE neurological examination, MRI when indicated, and clinical tone/asymmetry. Screening tools estimate risk, not certainty. A history of severe IVH, PVL, neonatal seizures or HIE increases surveillance needs. Start PT/OT, feeding, communication and family-centred intervention early; assess vision, hearing, nutrition, motor, adaptive, language and school function longitudinally. IAP high-risk neonatal follow-up and AIIMS protocols supply India-specific service pathways."}]}, {"title": "A7. Autism spectrum disorder — Indian 2026 clinical pathway", "blocks": [{"t": "p", "html": "ASD requires persistent deficits in social communication/interaction AND restricted or repetitive patterns of behaviour/interests, with developmental onset and functional impact. Early clues: poor social smile/response to name, reduced eye contact and joint attention, lack of pointing to share interest, atypical pretend play, stereotypies, insistence on sameness, unusual sensory responses and regression of language/social skills. Language delay alone does not establish ASD. Always consider hearing impairment and broader developmental profile."}, {"t": "p", "html": "<strong>SCREENING ≠ DIAGNOSIS  </strong>IAP 2026 recommends M-CHAT-R/F screening for approximately 16–30 months along with clinical evaluation. M-CHAT-R/F scoring anchor: 0–2 low risk (except special considerations for children under 24 months); 3–7 medium risk requires structured follow-up interview; 8–20 high risk warrants direct referral. A positive result is not diagnostic. Diagnostic assessment integrates history, direct observation, DSM-5/ICD-11 criteria and tools such as ADOS/CARS when indicated. Early intervention/referral should not wait for a final label when red flags are evident."}, {"t": "p", "html": "Management: parent-mediated communication strategies, structured developmental/behavioural interventions, speech-language therapy, OT for functional needs, educational inclusion and family support. Assess coexisting intellectual disability, epilepsy, sleep problems, ADHD, anxiety, feeding problems and sensory needs. Medication treats specific associated symptoms when indicated; it does not cure core ASD. Genetic assessment may be appropriate with dysmorphism, ID or significant comorbidities."}]}, {"title": "A8. ADHD and learning difficulty — do not mislabel", "blocks": [{"t": "p", "html": "ADHD diagnosis uses developmentally inappropriate inattention and/or hyperactivity-impulsivity with onset in childhood, clinically meaningful impairment in at least two settings, and exclusion of better explanations. Obtain parent and teacher collateral, developmental and school history, functional goals and validated rating scales (e.g., Vanderbilt/Conners). Evaluate sleep restriction/OSA, hearing/vision, anxiety, trauma, learning disorders, autism, seizures when suspected and medication effects."}, {"t": "p", "html": "<strong>IAP 2026 AGE-STRATIFIED CARE  </strong>Under 6 years: parent-training behavioural management and environmental/school routines first. Age 6–11: behavioural/educational supports and medication when impairment justifies it. Adolescents: medication plus psychosocial/CBT-style supports when appropriate. Stimulants are first-line pharmacological options when indicated; prescribe/titrate by trained clinicians and product guidance. The IAP 2026 document gives methylphenidate IR 2.5 mg twice daily as a typical starting example, with individual titration and formulation-specific limits; monitor appetite, sleep, weight, height, blood pressure, pulse and relevant cardiac history. This is NOT a universal dosing prescription."}, {"t": "p", "html": "Specific learning disorder is persistent difficulty in reading, written expression or mathematics despite adequate opportunity and targeted support; intelligence and adaptive skills may otherwise be normal. Dyslexia: decoding/fluency; dysgraphia: written expression; dyscalculia: number sense/calculation. ADHD and SLD commonly coexist. Evaluate teaching opportunity, language of instruction, hearing/vision, psychosocial context, adaptive function and psychoeducational profile; provide structured remediation and school accommodations. Poor grades alone do not diagnose intellectual disability."}]}, {"title": "A9. Sleep and behaviour — IAP 2026 overlay", "blocks": [{"t": "p", "html": "Use BEARS: Bedtime problems; Excessive daytime sleepiness; Awakenings; Regularity/duration; Snoring. Maintain a 2-week sleep diary if needed. Inadequate sleep can cause apparent hyperactivity and learning problems. Sleep terror is an NREM arousal in the first third of the night with confusion, autonomic activation and poor recall; nightmares are REM-related, usually later, with dream recall. Highly stereotyped brief focal motor episodes warrant evaluation for sleep-related epilepsy."}, {"t": "p", "html": "Obstructive sleep apnoea: loud habitual snoring, witnessed pauses, gasping, sweating, restless sleep, morning headaches, behavioural dysregulation, enlarged tonsils or obesity. Overnight polysomnography is the reference standard for diagnosis/severity. Actigraphy estimates activity/rest and cannot establish apnoea–hypopnoea index. A commonly used paediatric obstructive AHI severity anchor is mild 1–&lt;5, moderate 5–&lt;10 and severe ≥10 events/hour; thresholds vary by scoring system and society, so label the framework in exam stems. Adenotonsillectomy is frequently first-line for adenotonsillar OSA after appropriate evaluation; obesity and complex conditions raise residual-OSA risk."}, {"t": "p", "html": "Sleep management begins with regular bedtime/wake time, screen-free wind-down, appropriate activity, sleep diary and addressing environmental factors. Melatonin is specialist/context-dependent for selected sleep-onset/circadian problems, not a universal first-line treatment. Persistent snoring or daytime impairment warrants directed evaluation."}]}, {"title": "A10. Decision algorithms — exam-ready sequences", "blocks": [{"t": "p", "html": "<strong>ALGORITHM 1: ABNORMAL GROWTH  </strong>Accurate serial measurement → correct WHO/IAP chart → calculate velocity and MPH → classify weight-first vs height-first vs combined → examine puberty, proportion and systemic red flags → targeted tests (CBC/ESR, TSH/FT4, celiac with total IgA, renal etc. as indicated) → treat cause → repeat anthropometry and escalate if poor response."}, {"t": "p", "html": "<strong>ALGORITHM 2: DEVELOPMENTAL CONCERN  </strong>Clarify age/corrected age + domains → check regression, seizures, asymmetry or neurologic signs → hearing/vision assessment → standardized developmental/autism screening where indicated → targeted diagnostic evaluation and referrals → start early supports → reassess function and comorbidities."}, {"t": "p", "html": "<strong>ALGORITHM 3: SCHOOL INATTENTION  </strong>Confirm two-setting impairment + parent/teacher collateral → assess sleep/OSA, hearing, vision, anxiety and classroom factors → assess specific academic skills and adaptive function → ADHD/SLD/ASD differential → individualized school and family intervention → consider medication for confirmed impairing ADHD per IAP age framework → monitor goals and adverse effects."}]}, {"title": "A11. Close-discriminator matrix", "blocks": [{"t": "table", "head": ["<strong>Near-mimic pair</strong>", "<strong>Most decisive clue</strong>"], "rows": [["Familial stature vs constitutional delay", "Bone age ~chronological vs delayed; both often retain velocity"], ["Endocrine vs nutritional growth failure", "Height velocity falls with preserved BMI vs weight falls first"], ["ASD vs isolated expressive delay", "Joint attention and repetitive behaviours vs preserved reciprocity"], ["ADHD vs sleep deprivation / OSA", "Sleep symptoms and sleep study; reassess attention after correction"], ["SLD vs intellectual disability", "Circumscribed academic deficit vs broad adaptive impairment"], ["Sleep terror vs nightmare", "Early NREM confusion/amnesia vs late REM dream recall"], ["Sleep terror vs focal sleep epilepsy", "Variable prolonged arousal vs brief stereotyped focal events"], ["Delay vs regression", "Never acquired vs demonstrably lost skill"], ["GMA/HINE risk vs confirmed CP", "Predictive screening versus integrated clinical diagnosis"]]}]}, {"title": "A12. India-versus-international protocol distinctions", "blocks": [{"t": "p", "html": "IAP 2026 is the primary practical framework for growth charts, ASD, ADHD and sleep in this edition. Nelson 22e supplies the mechanism and differential framework. International CDC/AAP developmental screening at 9, 18, 30 months and autism-specific 18/24 months is presented only as a labelled comparison; it must not replace a stem explicitly asking for IAP. IAP 2026 uses M-CHAT-R/F for 16–30-month toddlers. The IAP growth-chart switch at age 5 is a particularly important India-specific exam discriminator. For OSA AHI cutoffs, scoring conventions vary: quote the framework rather than declaring a single universal threshold."}]}]}, {"id": "part-2", "title": "Comparative Coverage Addendum — Exam-Relevant Gaps", "eyebrow": "", "group": "Study Notes", "kind": "notes", "sections": [{"title": "A13. Puberty and Tanner staging — growth interpretation", "blocks": [{"t": "p", "html": "Girls: breast Tanner B2 is the usual first sign; boys: testicular volume ≥4 mL signals gonadarche. Conventional textbook boundaries: precocious puberty before 8 years in girls or 9 years in boys; delayed puberty when no breast development by 13 years or testicular enlargement by 14 years. Pubertal growth acceleration must be interpreted against Tanner stage, not only chronological age. Distinguish central (gonadotropin-dependent, progressive sequence) from peripheral puberty (sex-steroid exposure without normal hypothalamic–pituitary activation). Assessment: growth velocity, Tanner progression, bone age, and appropriately interpreted basal/stimulated gonadotropins."}]}, {"title": "A14. Obesity — Indian chart interpretation and red flags", "blocks": [{"t": "p", "html": "For Indian children aged 5–18 years, use IAP age- and sex-specific BMI reference curves with adult-equivalent 23 and 27 kg/m² lines; do not apply those adult BMI numbers directly to a child's BMI. Simple obesity usually preserves or accelerates linear growth. Obesity with decreasing height velocity warrants investigation for endocrine, hypothalamic, genetic or syndromic causes. Assess blood pressure, dysglycaemia, lipids, liver disease, sleep-disordered breathing and psychosocial burden; family-based longitudinal management is foundational."}]}, {"title": "A15. Cerebral palsy and GMFCS — neonatal-to-developmental bridge", "blocks": [{"t": "p", "html": "Cerebral palsy is a permanent disorder of movement and posture attributable to a non-progressive disturbance in the developing brain; its manifestations and secondary complications can change over time. GMFCS grades gross-motor function I–V, not muscle tone, MRI severity or aetiology. High-risk infant assessment integrates history, examination, General Movements Assessment, HINE and imaging where appropriate. Do not delay early intervention while waiting for diagnostic certainty. Follow feeding, growth, hips, vision, hearing, epilepsy, pain and participation."}]}, {"title": "A16. Hearing impairment and language delay", "blocks": [{"t": "p", "html": "Any speech delay, apparent autism phenotype or developmental regression requires hearing assessment even after a reportedly normal newborn screen. Otoacoustic emissions assess outer-hair-cell function; auditory brainstem response assesses neural pathway responses and can identify auditory neuropathy missed by OAE alone. The JCIH screen-by-1-month, diagnose-by-3-months, intervene-by-6-months benchmark is an international reference, not an automatically interchangeable Indian national programme rule. Choose age-appropriate audiological testing and early communication support."}]}, {"title": "A17. Rickets versus renal phosphate wasting", "blocks": [{"t": "p", "html": "Nutritional calcipenic rickets often features raised alkaline phosphatase and PTH with low 25-OH vitamin D or inadequate calcium intake; serum calcium can be normal. X-linked hypophosphataemia typically has renal phosphate wasting, low serum phosphate, raised ALP and inappropriately normal/low 1,25-(OH)₂D. Assess paired serum/urine phosphate handling and renal function where indicated. Treatment depends on mechanism: nutritional vitamin D/calcium replacement versus specialist-directed phosphate-active-vitamin-D or targeted therapy; do not substitute a universal dose without the applicable Indian protocol."}]}, {"title": "A18. Syndromic short stature and growth-hormone referral", "blocks": [{"t": "p", "html": "Turner syndrome: consider karyotyping in girls with unexplained short stature even without classic stigmata. Noonan syndrome: RASopathy phenotype, often congenital heart disease. Silver–Russell syndrome: SGA, relative macrocephaly, feeding difficulty and asymmetry. Prader–Willi syndrome: early hypotonia and feeding difficulty followed by hyperphagia. Disproportion suggests skeletal dysplasia. GH therapy is indication- and jurisdiction-specific; a low random GH level or single IGF-1 value is not diagnostic. Persistent short stature after SGA warrants specialist assessment rather than empiric calorie loading."}, {"t": "p", "html": "Protocol interpretation: Nelson 22e supplies the conceptual framework. Use IAP/IAP-NNF and relevant Indian national guidance for Indian clinical decisions when a directly applicable recommendation is available. International tools (DSM-5, M-CHAT-R/F, JCIH) are identified as such. Thresholds dependent on local policy should be confirmed against the named source before prescribing."}]}]}, {"id": "cases", "title": "Clinical Cases", "group": "Practice", "kind": "cases", "sections": [{"title": "Case 1 — Growth velocity beats percentile", "blocks": [{"t": "p", "html": "Clinical data: A 9-year-old girl was 125 cm a year ago and is now 128 cm; weight rose 27→33 kg. Her height has crossed from the 15th toward the 3rd centile. No diarrhoea. Pulse 62/min, dry skin and delayed bone age."}, {"t": "p", "html": "<strong>Structured reasoning:  </strong>Calculate 3 cm/year; low velocity with rising relative weight and hypothyroid signs favours endocrine failure."}, {"t": "p", "html": "<strong>Closest distractor:  </strong>Do not reassure from a single current centile or weight gain."}, {"t": "p", "html": "<strong>Next step:  </strong>Check TSH/free T4, then other causes as indicated; follow growth after treatment."}, {"t": "p", "html": "<strong>Exam trap:  </strong>Endocrine versus nutritional growth failure"}]}, {"title": "Case 2 — Familial versus constitutional", "blocks": [{"t": "p", "html": "Clinical data: A 12-year-old boy has height −2.4 SDS, growth 5.7 cm/year, bone age 9.5 years, no pubertal onset and a father who entered puberty at 16. CBC, ESR, thyroid and celiac screening are normal."}, {"t": "p", "html": "<strong>Structured reasoning:  </strong>Delayed skeletal maturity with preserved velocity and familial pubertal delay supports constitutional delay."}, {"t": "p", "html": "<strong>Closest distractor:  </strong>Familial short stature usually has bone age near chronological age."}, {"t": "p", "html": "<strong>Next step:  </strong>Monitor height velocity, puberty and psychosocial function; reassess if velocity falls."}, {"t": "p", "html": "<strong>Exam trap:  </strong>Normal variant versus hidden disease"}]}, {"title": "Case 3 — SGA without catch-up", "blocks": [{"t": "p", "html": "Clinical data: A child born SGA at 37 weeks is now 4 years old, height −2.9 SDS, weight-for-height normal, thyroid and celiac studies normal; no disproportion or chronic illness."}, {"t": "p", "html": "<strong>Structured reasoning:  </strong>Most SGA infants catch up by 2 years; persistent shortness at 4 years needs specialist evaluation."}, {"t": "p", "html": "<strong>Closest distractor:  </strong>Do not prescribe high-calorie feeds alone to force linear catch-up."}, {"t": "p", "html": "<strong>Next step:  </strong>Refer paediatric endocrinology to assess eligibility for therapy and alternatives."}, {"t": "p", "html": "<strong>Exam trap:  </strong>Catch-up timeline and referral threshold"}]}, {"title": "Case 4 — Preterm motor asymmetry", "blocks": [{"t": "p", "html": "Clinical data: A former 27-week infant with grade III IVH is seen at 4 months corrected age. Examination shows asymmetry, increased extensor tone and absent fidgety movements; weight is tracking appropriately."}, {"t": "p", "html": "<strong>Structured reasoning:  </strong>High risk for CP from convergent neonatal history, GMA and neurologic signs."}, {"t": "p", "html": "<strong>Closest distractor:  </strong>A normal weight trajectory does not rule out neurodevelopmental impairment."}, {"t": "p", "html": "<strong>Next step:  </strong>HINE and early PT/OT/developmental referral; plan longitudinal hearing/vision follow-up."}, {"t": "p", "html": "<strong>Exam trap:  </strong>High-risk screening versus diagnosis"}]}, {"title": "Case 5 — Language regression versus plateau", "blocks": [{"t": "p", "html": "Clinical data: A 23-month-old had 12 meaningful words at 18 months but now uses 3, no longer points to show objects, and has brief nocturnal staring episodes. Otoscopy is normal."}, {"t": "p", "html": "<strong>Structured reasoning:  </strong>True regression requires broad ASD, hearing and neurologic/epileptic evaluation."}, {"t": "p", "html": "<strong>Closest distractor:  </strong>Bilingualism and a simple late-talker plateau do not explain lost skills."}, {"t": "p", "html": "<strong>Next step:  </strong>Urgent developmental and hearing assessment; consider EEG if spells are convincing."}, {"t": "p", "html": "<strong>Exam trap:  </strong>Loss versus late acquisition"}]}, {"title": "Case 6 — ASD screen versus diagnosis", "blocks": [{"t": "p", "html": "Clinical data: A 20-month-old has no joint attention, lines up toys and resists routine change. Parent M-CHAT-R/F flags multiple items. Hearing status has not been assessed."}, {"t": "p", "html": "<strong>Structured reasoning:  </strong>Social communication plus repetitive behaviours raise ASD risk; M-CHAT is a screen."}, {"t": "p", "html": "<strong>Closest distractor:  </strong>A screen score does not independently establish DSM-5 diagnosis."}, {"t": "p", "html": "<strong>Next step:  </strong>Hearing testing, specialist developmental evaluation and immediate early supports."}, {"t": "p", "html": "<strong>Exam trap:  </strong>Two-domain phenotype and tool scope"}]}, {"title": "Case 7 — ADHD with coexisting dyslexia", "blocks": [{"t": "p", "html": "Clinical data: An 8-year-old boy is inattentive in home and school settings, reads haltingly with poor phonological decoding, has normal vision and hearing, and no intellectual/adaptive deficits. Sleep is adequate."}, {"t": "p", "html": "<strong>Structured reasoning:  </strong>ADHD and SLD-reading may coexist; both contribute to school difficulty."}, {"t": "p", "html": "<strong>Closest distractor:  </strong>Stimulant treatment alone cannot remediate decoding deficits."}, {"t": "p", "html": "<strong>Next step:  </strong>Parent/teacher scales, specialist ADHD assessment and structured reading remediation."}, {"t": "p", "html": "<strong>Exam trap:  </strong>Comorbidity rather than either/or"}]}, {"title": "Case 8 — OSA masquerading as behaviour", "blocks": [{"t": "p", "html": "Clinical data: A 7-year-old snores loudly, has witnessed apnoeas, daytime hyperactivity and declining marks. Tonsils 3+, BMI 92nd centile. PSG obstructive AHI 11/hour."}, {"t": "p", "html": "<strong>Structured reasoning:  </strong>This is clinically important OSA; sleep fragmentation can impair attention and learning."}, {"t": "p", "html": "<strong>Closest distractor:  </strong>A large tonsil alone cannot grade OSA, and ADHD may persist after airway care."}, {"t": "p", "html": "<strong>Next step:  </strong>Discuss ENT/sleep management, weight support and reassess residual symptoms."}, {"t": "p", "html": "<strong>Exam trap:  </strong>Confirmed OSA plus potential residual ADHD/SLD"}]}]}, {"id": "data", "title": "Data Interpretation", "group": "Practice", "kind": "data", "sections": [{"title": "Visual Station 1 — Serial height z-score trajectory", "blocks": [{"t": "p", "html": "<strong>Question:  </strong>A 9-year-old has a normal current BMI but height z-score has fallen over four years. Interpret the plotted trajectory."}, {"t": "img", "src": "img/image1.png", "alt": ""}, {"t": "p", "html": "Purpose-built educational schematic; not a patient image/recording or official reference chart."}, {"t": "p", "html": "<strong>Interpretation:  </strong>Progressive downward crossing to below −2 SDS: evaluate reduced growth velocity even if an isolated earlier height was normal."}, {"t": "p", "html": "<strong>Decisive visual/data features:  </strong>Steady loss of z-score across serial ages; position and slope are both abnormal."}, {"t": "p", "html": "<strong>Closest distractor / discriminator:  </strong>A stable child at −2 SDS may have familial short stature; this child is losing height position."}, {"t": "p", "html": "<strong>Next management step:  </strong>Verify measurement, calculate velocity, compare genetic target and evaluate systemic/endocrine causes."}, {"t": "p", "html": "<strong>Exam trap:  </strong>One normal height point does not negate a pathological slope."}, {"t": "p", "html": "<strong>Trace-back:  </strong>A1–A4"}]}, {"title": "Visual Station 2 — Velocity and deceleration", "blocks": [{"t": "p", "html": "<strong>Question:  </strong>Compare observed annual height gain with the age-related expected curve; identify the most concerning age interval."}, {"t": "img", "src": "img/image2.png", "alt": ""}, {"t": "p", "html": "Purpose-built educational schematic; not a patient image/recording or official reference chart."}, {"t": "p", "html": "<strong>Interpretation:  </strong>Velocity diverges below the expected prepubertal range after about age 6–7."}, {"t": "p", "html": "<strong>Decisive visual/data features:  </strong>The observed slope falls to approximately 3 cm/year by age 8 despite expected ~5–6."}, {"t": "p", "html": "<strong>Closest distractor / discriminator:  </strong>Physiologic slowing from 25 to 12 cm in infancy is normal; late prepubertal decline is not."}, {"t": "p", "html": "<strong>Next management step:  </strong>Repeat standardized measurements and pursue targeted growth-failure workup."}, {"t": "p", "html": "<strong>Exam trap:  </strong>Do not confuse age-related infant deceleration with pathological school-age decline."}, {"t": "p", "html": "<strong>Trace-back:  </strong>A2–A3"}]}, {"title": "Visual Station 3 — Developmental domain profile", "blocks": [{"t": "p", "html": "<strong>Question:  </strong>At chronological age 20 months, which domain is disproportionately affected in the plotted profile?"}, {"t": "img", "src": "img/image3.png", "alt": ""}, {"t": "p", "html": "Purpose-built educational schematic; not a patient image/recording or official reference chart."}, {"t": "p", "html": "<strong>Interpretation:  </strong>Social communication is the most impaired domain, followed by language; motor skills are relatively preserved."}, {"t": "p", "html": "<strong>Decisive visual/data features:  </strong>Social skill-age about 10 months despite gross motor about 18 months."}, {"t": "p", "html": "<strong>Closest distractor / discriminator:  </strong>Isolated language disorder may preserve joint attention; this profile requires ASD/social communication assessment."}, {"t": "p", "html": "<strong>Next management step:  </strong>Hearing assessment and structured developmental/ASD evaluation with early supports."}, {"t": "p", "html": "<strong>Exam trap:  </strong>Do not label GDD without considering the pattern and number of impaired domains."}, {"t": "p", "html": "<strong>Trace-back:  </strong>A5–A7"}]}, {"title": "Visual Station 4 — Simplified respiratory tracing", "blocks": [{"t": "p", "html": "<strong>Question:  </strong>During a 60-second segment, airflow decreases while respiratory effort persists; saturation dips after the event. Identify the event type."}, {"t": "img", "src": "img/image4_q.png", "alt": ""}, {"t": "img", "src": "img/image4.png", "alt": "", "reveal": true, "caption": "Labelled schematic from the source document"}, {"t": "p", "html": "Purpose-built educational schematic; not a patient image/recording or official reference chart."}, {"t": "p", "html": "<strong>Interpretation:  </strong>Obstructive respiratory event is more likely than central apnoea."}, {"t": "p", "html": "<strong>Decisive visual/data features:  </strong>Marked airflow reduction with maintained effort and delayed desaturation."}, {"t": "p", "html": "<strong>Closest distractor / discriminator:  </strong>Central apnoea would show absent airflow AND absent respiratory effort; desaturation alone is nonspecific."}, {"t": "p", "html": "<strong>Next management step:  </strong>Review full PSG, OSA severity and airway anatomy; plan management by clinical context."}, {"t": "p", "html": "<strong>Exam trap:  </strong>This is a teaching trace, not a validated clinical PSG recording."}, {"t": "p", "html": "<strong>Trace-back:  </strong>A9"}]}, {"title": "Visual Station 5 — Plateau versus regression", "blocks": [{"t": "p", "html": "<strong>Question:  </strong>A toddler initially acquires words and shared-attention behaviours but subsequently loses both on the plotted trajectory. How does the differential change?"}, {"t": "img", "src": "img/image5_q.png", "alt": ""}, {"t": "img", "src": "img/image5.png", "alt": "", "reveal": true, "caption": "Labelled schematic from the source document"}, {"t": "p", "html": "Purpose-built educational schematic; not a patient image/recording or official reference chart."}, {"t": "p", "html": "<strong>Interpretation:  </strong>The decline is regression, not merely delayed acquisition; broaden the workup."}, {"t": "p", "html": "<strong>Decisive visual/data features:  </strong>Previously attained abilities fall after approximately 20–22 months."}, {"t": "p", "html": "<strong>Closest distractor / discriminator:  </strong>A plateau stays flat without loss; true regression raises ASD, epilepsy, hearing and neurodegenerative concerns."}, {"t": "p", "html": "<strong>Next management step:  </strong>Prompt developmental and hearing assessment; targeted neurologic testing if spells or focal signs."}, {"t": "p", "html": "<strong>Exam trap:  </strong>Do not attribute documented loss to bilingualism or late talking."}, {"t": "p", "html": "<strong>Trace-back:  </strong>A5–A7"}]}]}, {"id": "revision", "title": "Rapid Revision", "group": "Practice", "kind": "revision", "sections": [{"title": "", "blocks": [{"t": "p", "html": "<strong>Chart and index:  </strong>WHO 0–5 y; IAP 2015 5–18 y. Short stature height SDS &lt;−2. Stunting height-for-age &lt;−2; wasting weight-for-height &lt;−2; severe wasting &lt;−3. IAP age-specific BMI adult-equivalent 23/27 lines."}, {"t": "p", "html": "<strong>Velocity and target:  </strong>Height gains ~25 cm in first year, 12 in second, 7–8 age 2–4, 5–6 prepubertal. Velocity = delta height ×12/months. MPH boy (F+M+13)/2; girl (F+M−13)/2. Assess centile crossing and MPH discordance."}, {"t": "p", "html": "<strong>Growth patterns:  </strong>Familial: normal velocity/normal bone age/short family. Constitutional: delayed bone age, later puberty, preserved velocity. Endocrine: low height velocity with normal/high BMI. Nutritional/systemic: weight falls before height. Dysplasia: disproportion."}, {"t": "p", "html": "<strong>SGA / faltering:  </strong>Most SGA catch up by 2 y; persistent height &lt;−2 to −2.5 SDS at 3–4 y → specialist review. Growth faltering: falling weight trajectory, repeated &lt;3rd centile or SDS &lt;−2; red flags oedema, diarrhoea, infections, regression, height decline."}, {"t": "p", "html": "<strong>Development:  </strong>IAP: head control ~3–4 mo; independent sit ~9 mo; pincer ~12–15 mo; walk ~12–15 mo; two-word phrases ~2 y; circle ~3 y; cross ~4 y; triangle ~5 y. Correct age for prematurity. Any true regression requires assessment."}, {"t": "p", "html": "<strong>ASD / language:  </strong>ASD = social-communication deficit + restricted/repetitive behaviour. Joint attention and pretend play are discriminators. M-CHAT-R/F 16–30 mo is SCREEN only. Hearing testing remains essential with language delay."}, {"t": "p", "html": "<strong>ADHD / SLD:  </strong>ADHD = impairing symptoms in ≥2 settings; evaluate sleep, learning, anxiety, vision/hearing. Under 6: parent-training behaviour first. School-age: combined school/behaviour + medication when indicated. SLD may coexist with ADHD; reading, writing, maths are distinct domains."}, {"t": "p", "html": "<strong>Sleep:  </strong>BEARS; OSA = snoring + pauses/gasping + daytime symptoms. PSG gold standard, actigraphy adjunct. Paediatric AHI rough anchor mild 1–&lt;5, moderate 5–&lt;10, severe ≥10 (scoring-system caveat). Sleep terror early NREM with amnesia; nightmare later REM with recall; focal stereotyped events → consider epilepsy."}, {"t": "p", "html": "<strong>Management sequence:  </strong>Growth: measure → chart → velocity/MPH → pattern → red flags → targeted tests → treat → remeasure. Development: correct age → check regression/qualitative signs → hearing/vision → screen → specialist evaluation → start early intervention."}, {"t": "p", "html": "<strong>Notebook repairs:  </strong>CPS transitional hypoglycemia &lt;72 h versus PES persistent evaluation after 48 h (international-only comparison); physiologic neonatal natriuresis; dextrose % = GIR×144/fluids; low ketones+low FFA+glucagon rise ≥30 mg/dL supports excess insulin action."}]}]}, {"id": "quizzes", "title": "Quizzes", "group": "Practice", "kind": "quizzes", "sections": []}, {"id": "recall", "title": "Active Recall", "group": "Revise", "kind": "recall", "sections": [{"title": "", "blocks": [{"t": "list", "ordered": true, "items": ["Which chart for 0–5 years and which for 5–18 years in India?<br>Answer: WHO 2006 for 0–5 years; revised IAP 2015 for 5–18 years.", "What do adult-equivalent BMI 23 and 27 mean on IAP charts?<br>Answer: Age-specific curves corresponding to adult BMI 23 overweight and 27 obesity; never directly compare child BMI to 23/27.", "State the height velocity sequence: year 1, year 2, ages 2–4, 4 to puberty.<br>Answer: ~25, 12, 7–8 and 5–6 cm/year, respectively.", "Give both mid-parental target-height formulas.<br>Answer: Boy: (father + mother + 13)/2; girl: (father + mother − 13)/2, all in cm.", "Calculate velocity for a gain of 3.2 cm in 8 months.<br>Answer: 3.2 × 12/8 = 4.8 cm/year.", "Bone age in familial stature versus constitutional delay?<br>Answer: Familial: bone age ~chronological; constitutional delay: delayed bone age with usually preserved prepubertal velocity.", "What growth pattern suggests endocrine disease?<br>Answer: Falling height velocity with preserved/increased relative weight or BMI.", "What is the key distinction between stunting and wasting?<br>Answer: Height-for-age &lt;−2 SDS versus weight-for-height/length &lt;−2 SDS.", "When is persistent SGA short stature referred?<br>Answer: Most catch up by age 2; persistent height SDS below about −2 to −2.5 at 3–4 years merits specialist evaluation.", "What is the formula for corrected age?<br>Answer: Chronological age − (40 − gestational age at birth in weeks).", "At what age does IAP 2026 list independent sitting and mature pincer?<br>Answer: Independent sitting ~9 months; mature pincer ~12–15 months.", "What language/social features around age 2 are high-yield?<br>Answer: Two-word phrases, pointing/shared interest, reciprocal play; no meaningful phrases or joint attention is concerning.", "Differentiate developmental delay from regression.<br>Answer: Delay = not yet acquired; regression = loss of previously acquired skill, needing urgent evaluation.", "State the two core domains of ASD.<br>Answer: Social communication/interaction deficits AND restricted/repetitive behaviour/interests.", "M-CHAT-R/F age range and purpose?<br>Answer: About 16–30 months; risk screening with follow-up, not definitive diagnosis.", "What assessment must accompany isolated speech delay?<br>Answer: Hearing assessment, with developmental/language evaluation.", "How is ADHD impairment established?<br>Answer: Symptoms and meaningful functional impairment across at least two settings, with collateral reports and differential assessment.", "IAP ADHD initial approach under 6 years?<br>Answer: Parent-training behavioural management and environmental/school structure first.", "SLD versus ID discriminator?<br>Answer: Circumscribed academic skill deficit with preserved broader adaptive function versus global intellectual/adaptive deficits.", "State BEARS.<br>Answer: Bedtime problems, Excessive daytime sleepiness, Awakenings, Regularity/duration, Snoring.", "Sleep terror versus nightmare?<br>Answer: Early-night NREM confusion/amnesia versus later REM vivid dream recall.", "What is the gold-standard investigation for suspected OSA?<br>Answer: Overnight polysomnography; actigraphy cannot directly score respiratory events.", "Visual pattern: falling height z-score with rising BMI?<br>Answer: Concerning for endocrine growth failure; measure velocity and evaluate clinically.", "Visual pattern: airflow ceases but effort persists?<br>Answer: Obstructive event; absent effort too would suggest central apnoea.", "Visual pattern: toddler skill count rises then falls?<br>Answer: Developmental regression; assess ASD, hearing, epilepsy and neurologic/metabolic causes as indicated."]}]}]}, {"id": "notebook", "title": "Error Notebook", "group": "Revise", "kind": "notebook", "sections": []}, {"id": "plan", "title": "Revision Plan", "group": "Revise", "kind": "plan", "sections": [{"title": "Self-Assessment & Spaced-Review Tracker", "h1": "Self-Assessment & Spaced-Review Tracker", "blocks": [{"t": "table", "head": ["<strong>Metric</strong>", "<strong>Record</strong>"], "rows": [["Base MCQs", "____ / 75"], ["Basic / Recall", "____ / 7"], ["Conceptual", "____ / 13"], ["Clinical / Application", "____ / 27"], ["High-Difficulty", "____ / 20"], ["Integrated / Rank-Differentiating", "____ / 8"], ["Notebook Retests — Extra", "____ / 4"], ["Visual Stations", "____ / 5"], ["Active Recall", "____ / 25"], ["Calculation Drill", "Not scheduled on Day 13 (odd day)"]]}, {"t": "p", "html": "RAG rules (self-rating): GREEN = correct with clear reasoning and no hint; AMBER = correct by guess or uncertain between close distractors; RED = incorrect or unable to explain. Record every RED/AMBER item in the error notebook using K/C/R/G/S; retain historical failures even after a correct retest."}, {"t": "p", "html": "Spaced review: R1 ~24–72 h after error; R2 ~7 days; R3 ~21 days. Retest source concepts only after confirmation. Due but unresolved original concept: Day 5 Q4 remains withheld pending original stem; a newly reported Day 10 Q65 concept is not available in the retrieved notebook and is not invented. Four resolved Day 10 concepts are retested in this document; successful completion should be recorded before moving them to Improving."}]}]}, {"id": "references", "title": "References", "group": "More", "kind": "notes", "sections": [{"title": "Source Notes — Verified 11 October 2026", "h1": "Source Notes — Verified 11 October 2026", "blocks": [{"t": "p", "html": "Nelson Textbook of Pediatrics, 22nd ed. — Primary conceptual reference; standard growth/development and differential reasoning; textbook not reproduced verbatim."}, {"t": "p", "html": "IAP Presidential Action Plan 2026: Understanding Growth Charts — https://iapindia.org/pdf/action-plan-2026/Growth-Development-and-Behaviour/001-Understanding-Growth-Charts.pdf"}, {"t": "p", "html": "IAP 2026: Growth Faltering, Catch-Up Growth and Early Obesity — https://iapindia.org/pdf/action-plan-2026/Growth-Development-and-Behaviour/002-Growth-Faltering-Catch-Up-Growth-and-Early-Obesity.pdf"}, {"t": "p", "html": "IAP 2026: Short Stature, Non-Endocrine Causes — https://iapindia.org/pdf/action-plan-2026/Growth-Development-and-Behaviour/003-Short-Stature.pdf"}, {"t": "p", "html": "IAP 2026: Physical Developmental Milestones — https://iapindia.org/pdf/action-plan-2026/Growth-Development-and-Behaviour/004-Physical-Developmental-Milestones.pdf"}, {"t": "p", "html": "IAP 2026: Autism Recognition — https://iapindia.org/pdf/action-plan-2026/Neurodevelopment/006-Autism-Recognition-Clinical-Clues-and-Early-Diagnosis.pdf"}, {"t": "p", "html": "IAP 2026: ADHD Management — https://iapindia.org/pdf/action-plan-2026/Neurodevelopment/011-Attention-Matters-Strategies-in-ADHD-Management.pdf"}, {"t": "p", "html": "IAP 2026: Learning Difficulties in Children — https://iapindia.org/pdf/action-plan-2026/Growth-Development-and-Behaviour/008-Learning-Difficulties-in-Children.pdf"}, {"t": "p", "html": "IAP 2026: Sleep Disorders in Children — https://iapindia.org/pdf/action-plan-2026/Growth-Development-and-Behaviour/012-Sleep-Disorders-in-Children.pdf"}, {"t": "p", "html": "IAP Growth Charts (official) — https://www.iapindia.org/iap-growth-charts/"}, {"t": "p", "html": "WHO: Child Growth and Malnutrition Definitions — https://www.who.int/data/nutrition/nlis/info/malnutrition-in-children"}, {"t": "p", "html": "Cloherty &amp; Stark Manual of Neonatal Care; IAP-NNF and AIIMS newborn follow-up resources — Cross-topic neonatal care and developmental surveillance; use current India-specific care pathways."}, {"t": "p", "html": "CDC 2026 Developmental Monitoring/Screening — International comparison ONLY: https://www.cdc.gov/act-early/about/developmental-monitoring-and-screening.html"}]}, {"title": "Source Comparison & Editorial Audit", "h1": "Source Comparison & Editorial Audit", "blocks": [{"t": "p", "html": "Compared source A: attached Day 13 Revised V4 (32 pages), including puberty, obesity, CP, hearing, rickets and syndromic growth sections and six simulated data stations."}, {"t": "p", "html": "Compared source B: previously generated Day 13 standalone DOCX, containing 75 base MCQs, four extra notebook retests, detailed Section C option-by-option explanations, separate Active Recall answers and five visual stations."}, {"t": "p", "html": "Editorial decision: retain the 75 + 4 scored-question structure and fuller Section C of source B; integrate six omitted teaching areas from source A. Do not import V4's six gap-fill questions into the locked base-MCQ count."}, {"t": "p", "html": "V4 had explicit unresolved 'verify' tags and a shortened answer key; these were not imported. Claims needing source-specific confirmation are framed conservatively rather than presented as verified IAP 2026 wording."}, {"t": "p", "html": "Limitations: this comparison-driven edition does not establish that every numerical threshold, notebook source concept or MCQ answer has been independently verified against the latest primary-source guideline. A full item-by-item medical validation remains necessary before treating it as an authoritative exam key."}]}]}], "quizSets": [{"k": 1, "from": 1, "to": 16, "n": 16}, {"k": 2, "from": 17, "to": 32, "n": 16}, {"k": 3, "from": 33, "to": 48, "n": 16}, {"k": 4, "from": 49, "to": 64, "n": 16}, {"k": 5, "from": 65, "to": 79, "n": 15}], "mcqCount": 79};
